   try{switch($action.operation){
    {$_ -in 'C','Count','Bytes','Chars'}{$write=$action.operation -ne 'Count';$n=$action.units.Length;$sourceValue=$null;if($direction -eq 'encoder'){$sourceValue=[char[]](@(0xDC00)+[int[]]$action.units+@(0xD800));if($write){$target=[byte[]]::new([int]$action.capacity+3)}}else{$sourceValue=[byte[]](@(255)+[int[]]$action.units+@(255));if($write){$target=[char[]]::new([int]$action.capacity+3)}};if($write){for($i=0;$i -lt $target.Length;$i++){$target[$i]=99}};$size=if($action.operation -eq 'C'){10}elseif($write){8}else{5};$argsValue=[object[]]::new($size);$argsValue[0]=$state;$argsValue[1]=$sourceValue;$argsValue[2]=[int]1;$argsValue[3]=[int]$n;if($write){$argsValue[4]=$target;$argsValue[5]=[int]1;$argsValue[6]=[int]$action.capacity;$argsValue[7]=[bool]$action.flush}else{$argsValue[4]=[bool]$action.flush};if($action.operation -eq 'C'){$argsValue[8]=$used;$argsValue[9]=$completed;$bridges[$direction+'False'].DynamicInvoke($argsValue)|Out-Null;$value=0}else{$value=[int]$methodBridges[$direction+[string]$write].DynamicInvoke($argsValue)};$result=[ordered]@{ok=$true;count=$value}}
    'Reset'{$state.Reset();$result=[ordered]@{ok=$true}}
