    'Replace'{$replacement=if($direction -eq 'encoder'){[Text.EncoderReplacementFallback]::new('AB')}else{[Text.DecoderReplacementFallback]::new('AB')};$owner.GetProperty('Fallback').SetMethod.Invoke($state,[object[]]@($replacement))|Out-Null;$result=[ordered]@{ok=$true}}
